{
  "references": [
    {
      "id": "R1",
      "summary_ko": "남자가 점핑잭 동작을 하고 있으나 그 동작이 발레 앙 푸앵트처럼 이상해 보임.",
      "claims": [
        {
          "id": "R1.S1",
          "evidence": "the man, while technically jumping, but is most noticeably doing jumping jacks",
          "symptom_ko": "남자가 점핑잭 동작을 수행하고 있음",
          "is_anomaly": false
        },
        {
          "id": "R1.S2",
          "evidence": "the jumping jack motion looks odd, almost like en pointe ballet",
          "symptom_ko": "점핑잭 동작이 발레의 앙 푸앵트처럼 이상해 보임",
          "is_anomaly": true
        }
      ]
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "점프 동작 중 남자의 스웨트셔츠에 있는 그래픽/텍스트 프린트가 지속적으로 변형되고 깜빡이며 모양이 바뀜."
    },
    {
      "id": "C2",
      "summary_ko": "빠른 움직임 구간에서 남자의 이목구비와 머리 윤곽이 부자연스럽게 왜곡되고 흐려짐."
    },
    {
      "id": "C3",
      "summary_ko": "점프 주기 전반에 걸쳐 스웨트셔츠의 그래픽 프린트와 글자가 일관되지 않게 변형되고 늘어나며 모양이 바뀜."
    },
    {
      "id": "C4",
      "summary_ko": "수직 점프 및 착지 중 얼굴 이목구비가 뚜렷하게 흐려지고 왜곡되며 모양이 바뀜."
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "target_relation": "different",
      "event_relation": "different",
      "description_consistency": "insufficient",
      "conflict_scope": "uncertain",
      "reference_claim_ids": [
        "R1.S2"
      ],
      "reference_evidence": "",
      "candidate_evidence": "",
      "shared_event_ko": "",
      "conflicts_ko": [
        "레퍼런스는 남자의 점핑잭 동작 자체(발레 앙 푸앵트 같은 부자연스러움)를 이상 현상으로 보고 있으나, 후보는 스웨트셔츠 프린트의 변형 및 깜빡임을 설명하고 있음"
      ],
      "reason_ko": "대상과 결함 유형이 완전히 다른 현상입니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "target_relation": "different",
