      "description_consistency": "insufficient",
      "conflict_scope": "uncertain",
      "reference_claim_ids": [
        "R1.S2"
      ],
      "reference_evidence": "",
      "candidate_evidence": "",
      "shared_event_ko": "",
      "conflicts_ko": [
        "레퍼런스는 남자의 점핑잭 동작(자세/움직임) 이상을 다루는 반면, 후보는 점프 중 얼굴 이목구비의 흐려짐과 형태 변형을 다룸"
      ],
      "reason_ko": "전체 신체 동작 이상과 얼굴 형태 왜곡은 대상 및 결함 현상이 다릅니다."
    }
  ]
}

